472	// CreateHandover 由交班班次向同岗位接班班次发起交接。
473	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
474	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
475	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
476	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
477	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
478	// 要求仅对首次发起生效。
479	// 只有本地数据保存成功才算发起完成：首次发起的输入与班次状态均合法、实际进入
480	// 保存阶段后写盘失败时，内存变更随快照一并回滚，返回原保存错误与零值交接结果
481	// （编号、岗位、两班编号为空，发起时间为零值，完成时间为空，清单没有事项），
482	// 不把尚未保存的编号、发起时间、清单或空清单的完成时间当作发起结果；失败尝试
483	// 不占用交接编号，也不留下已指定接班对象的关系。
484	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
485		fromShiftID = clean(fromShiftID)
486		toShiftID = clean(toShiftID)
487	
488		var result Handover
489		// saved 标记业务变更是否已完整执行、只待落盘：此后出现的错误只能是保存
490		// 阶段失败，而不是业务拒绝。
491		saved := false
492		err := svc.store.mutate(func(d *Data) error {
493			from, _ := findShift(d, fromShiftID)
494			to, _ := findShift(d, toShiftID)
495			if from == nil {
496				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
497			}
498			if to == nil {
499				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
500			}
501			if from.ID == to.ID {
502				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
503			}
504			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
505			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
506			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
507			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
508			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
509			// 存在与交给自身的校验仍在其前。
510			for i := range d.Handovers {
511				if d.Handovers[i].FromShiftID == from.ID {
512					existing := &d.Handovers[i]
513					// 即使以“已存在”错误返回，交出的也是独立副本，调用方改动
514					// 不影响系统保存的原交接记录。
515					result = cloneHandover(*existing)
516					if existing.ToShiftID != to.ID {
517						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
518							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
519					}
520					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
521				}
522			}
523	
524			if from.Position != to.Position {
525				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
526					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
527			}
528	
529			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
530			// 交班班次已经结束，重叠区间须有有效说明（正文去掉首尾空白后仍有内容，
531			// 只凭说明记录存在不算）。
532			if to.Closed {
533				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
534			}
535			if to.Start.Before(from.Start) {
536				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
537					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
538					from.ID, from.Start.Format(time.RFC3339))
539			}
540			if !from.Closed {
541				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
542					ErrShiftNotClosed, from.ID)
543			}
544			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasEffectiveNote(d, from.ID, to.ID) {
545				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
546					ErrOverlap, from.ID, to.ID)
547			}
548	
549			entries := []HandoverEntry{}
550			for i := range d.Items {
551				it := &d.Items[i]
552				if it.CurrentShiftID == from.ID && !it.Closed {
553					entries = append(entries, HandoverEntry{
554						ItemID:      it.ID,
555						Content:     it.Content,
556						Severity:    it.Severity,
557						Constraints: it.Constraints,
558						FollowOwner: it.FollowOwner,
559						Status:      EntryPending,
560					})
561				}
562			}
563			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
564	
565			d.HandoverSeq++
566			now := svc.now()
567			h := Handover{
568				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
569				Position:    from.Position,
570				FromShiftID: from.ID,
571				ToShiftID:   to.ID,
572				CreatedAt:   now,
573				Entries:     entries,
574			}
575			if len(entries) == 0 {
576				// 空清单直接完成。
577				h.CompletedAt = &now
578			}
579			d.Handovers = append(d.Handovers, h)
580			result = cloneHandover(h)
581			saved = true
582			return nil
583		})
584		if err != nil {
585			if saved {
586				// 业务校验全部通过、实际进入保存阶段后失败：内存已随快照回滚，
587				// 不能把尚未保存的新交接（编号、发起时间、清单与空清单的完成时间）
588				// 当作发起结果交给调用方。
589				return Handover{}, err
590			}
591			// 业务拒绝：重复发起与改换对象仍按承诺返回保存的原记录。
592			return result, err
593		}
594		return result, nil
595	}
596	
597	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
598	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
599	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
600	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
601	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
602	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
603	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
604	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
605		handoverID = clean(handoverID)
606		itemID = clean(itemID)
607		operator = clean(operator)
608		reason = clean(reason)
609		trackingNote = clean(trackingNote)
610		nextFollowOwner = clean(nextFollowOwner)
611	
612		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
613			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
614		}
615		if err := requireNonEmpty("操作人", operator); err != nil {
616			return Handover{}, err
617		}
618	
619		var result Handover
620		err := svc.store.mutate(func(d *Data) error {
621			h, _ := findHandover(d, handoverID)
622			if h == nil {
623				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
624			}
625			e, _ := findEntry(h, itemID)
626			if e == nil {
627				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
628			}
629			if e.Status.Received() {
630				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
631					ErrHandoverState, e.ItemID, e.Status.Label())
632			}
633			if e.Status == EntryReturned {
634				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
635				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
636				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
637				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
638					ErrHandoverState, e.ItemID, h.ID)
639			}
640			switch action {
641			case ActionReturn:
642				if err := requireNonEmpty("退回原因", reason); err != nil {
643					return err
644				}
645			case ActionTrack:
646				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
647					return err
648				}
649				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
650					return err
651				}
652			}
653	
654			now := svc.now()
655			switch action {
656			case ActionConfirm:
657				e.Status = EntryConfirmed
658			case ActionTrack:
659				e.Status = EntryTracking
660				e.TrackingNote = trackingNote
661				e.FollowOwner = nextFollowOwner
662			case ActionReturn:
663				e.Status = EntryReturned
664				e.Rounds = append(e.Rounds, ReturnRound{
665					Seq:            len(e.Rounds) + 1,
666					ReturnedAt:     now,
667					ReturnOperator: operator,
668					Reason:         reason,
669				})
670			}
671			e.Operator = operator
672			e.ProcessedAt = &now
673	
674			if action != ActionReturn {
675				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
676				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
677					it.CurrentShiftID = h.ToShiftID
678					if !contains(it.ShiftIDs, h.ToShiftID) {
679						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
680					}
681					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
682					if action == ActionTrack {
683						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
684						it.FollowOwner = nextFollowOwner
685					}
686					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
687				}
688			}
689	
690			if h.Completed() {
691				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
692				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
693				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
694				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
695				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
696				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
697				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
698				// 项无法再处理，完成时间不会被改写。
699				h.CompletedAt = &now
700			}
701			// 返回独立副本：调用方保留的处理结果（含逐项处理时间、退回/补充记录
702			// 与完成时间）不与系统保存的交接共享内存。
703			result = cloneHandover(*h)
704			return nil
705		})
706		return result, err
707	}
708	
709	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
710	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
711	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
712	
713	func contains(xs []string, x string) bool {
714		for _, v := range xs {
715			if v == x {
716				return true
717			}
718		}
719		return false
720	}
721	
722	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
723	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
724	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
725	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
726	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
727	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
728	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
729		handoverID = clean(handoverID)
730		itemID = clean(itemID)
731		operator = clean(operator)
732		supplement = clean(supplement)
733		if err := requireNonEmpty("操作人", operator); err != nil {
734			return Handover{}, err
735		}
736		if err := requireNonEmpty("补充说明", supplement); err != nil {
737			return Handover{}, err
738		}
739	
740		var result Handover
741		err := svc.store.mutate(func(d *Data) error {
742			h, _ := findHandover(d, handoverID)
743			if h == nil {
744				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
745			}
746			e, _ := findEntry(h, itemID)
747			if e == nil {
748				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
749			}
750			if e.Status != EntryReturned {
751				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
752					ErrHandoverState, e.ItemID, e.Status.Label())
753			}
754			if len(e.Rounds) == 0 {
755				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
756			}
757			round := &e.Rounds[len(e.Rounds)-1]
758			if round.ResubmittedAt != nil {
759				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
760			}
761			now := svc.now()
762			round.Supplement = supplement
763			round.SupplementOperator = operator
764			round.SupplementAt = &now
765			round.ResubmittedAt = &now
766			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
767			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
768			e.Status = EntryPending
769			e.Operator = ""
770			e.ProcessedAt = nil
771			// 返回独立副本：调用方保留的重新提交结果不与系统保存的交接共享内存。
772			result = cloneHandover(*h)
773			return nil
774		})
775		return result, err
776	}
777	
778	// GetShift 按编号查询班次。返回独立副本：改动结果不影响系统保存的记录。
779	func (svc *Service) GetShift(id string) (Shift, error) {
780		sh, _ := findShift(&svc.store.data, clean(id))
781		if sh == nil {
782			return Shift{}, fmt.Errorf("%w：班次 %s", ErrNotFound, id)
783		}
784		return cloneShift(*sh), nil
785	}
786	
787	// ListShifts 返回全部班次，按编号排序；每个班次都是独立副本。
788	func (svc *Service) ListShifts() []Shift {
789		out := make([]Shift, len(svc.store.data.Shifts))
790		for i, sh := range svc.store.data.Shifts {
791			out[i] = cloneShift(sh)
792		}
793		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
794		return out
795	}
796	
797	// GetItem 按稳定编号查询事项。返回独立副本：流经班次、历史事件与关闭时间
798	// 都与存储中的记录脱离，改动结果不影响系统保存的记录。
799	func (svc *Service) GetItem(id string) (Item, error) {
800		it, _ := findItem(&svc.store.data, clean(id))
801		if it == nil {
802			return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
803		}
804		return cloneItem(*it), nil
805	}
806	
807	// GetHandover 按编号查询交接。返回独立副本：清单各项（含处理时间与历次
808	// 退回/补充记录）与完成时间都与存储中的记录脱离，改动结果不影响系统保存的记录。
809	func (svc *Service) GetHandover(id string) (Handover, error) {
810		h, _ := findHandover(&svc.store.data, clean(id))
811		if h == nil {
812			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
813		}
814		return cloneHandover(*h), nil
815	}
816	
817	// ListHandovers 返回全部交接记录，按编号排序；每份交接都是独立副本。
818	func (svc *Service) ListHandovers() []Handover {
819		out := make([]Handover, len(svc.store.data.Handovers))
820		for i, h := range svc.store.data.Handovers {
821			out[i] = cloneHandover(h)
822		}
823		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
824		return out
825	}
826	
827	// OverlapNotes 返回涉及指定班次的全部重叠说明。
828	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
829		shiftID = clean(shiftID)
830		out := []OverlapNote{}
831		for _, n := range svc.store.data.Notes {
832			if n.ShiftA == shiftID || n.ShiftB == shiftID {
833				out = append(out, n)
834			}
835		}
836		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
837		return out
838	}
839	
840	// cloneTimePtr 复制时间指针，nil 保持 nil。
841	func cloneTimePtr(t *time.Time) *time.Time {
842		if t == nil {
843			return nil
844		}
845		v := *t
846		return &v
847	}
848	
849	// cloneItem 深拷贝事项：流经班次、历史事件与关闭时间都与存储中的记录脱离。
850	func cloneItem(it Item) Item {
851		out := it
852		out.ShiftIDs = append([]string(nil), it.ShiftIDs...)
853		out.Events = append([]ItemEvent(nil), it.Events...)
854		out.ClosedAt = cloneTimePtr(it.ClosedAt)
855		return out
856	}
857	
858	// cloneCloseItemSnapshot 深拷贝结束时事项快照（含关闭时间指针）。
859	func cloneCloseItemSnapshot(s CloseItemSnapshot) CloseItemSnapshot {
860		out := s
861		out.ClosedAt = cloneTimePtr(s.ClosedAt)
862		return out
863	}
864	
865	// cloneCloseRecord 深拷贝班次结束时记录；nil 保持 nil，
866	// 空清单仍是非 nil 记录，与缺少结束时记录的旧数据相区别。
867	func cloneCloseRecord(rec *ShiftCloseRecord) *ShiftCloseRecord {
868		if rec == nil {
869			return nil
870		}
871		out := &ShiftCloseRecord{}
872		if rec.Items != nil {
873			out.Items = make([]CloseItemSnapshot, len(rec.Items))
874			for i, s := range rec.Items {
875				out.Items[i] = cloneCloseItemSnapshot(s)
876			}
877		}
878		return out
879	}
880	
881	// cloneShift 深拷贝班次：关闭时间与结束时记录都与存储中的记录脱离。
882	func cloneShift(sh Shift) Shift {
883		out := sh
884		out.ClosedAt = cloneTimePtr(sh.ClosedAt)
885		out.CloseRecord = cloneCloseRecord(sh.CloseRecord)
886		return out
887	}
888	
889	// cloneEntry 深拷贝交接单项：处理时间与历次退回/补充记录都与存储中的记录脱离。
890	func cloneEntry(e HandoverEntry) HandoverEntry {
891		out := e
892		out.ProcessedAt = cloneTimePtr(e.ProcessedAt)
893		if e.Rounds != nil {
894			out.Rounds = make([]ReturnRound, len(e.Rounds))
895			for i, r := range e.Rounds {
896				out.Rounds[i] = r
897				out.Rounds[i].SupplementAt = cloneTimePtr(r.SupplementAt)
898				out.Rounds[i].ResubmittedAt = cloneTimePtr(r.ResubmittedAt)
899			}
900		}
901		return out
902	}
903	
904	// cloneHandover 深拷贝交接记录：完成时间与清单各项都与存储中的记录脱离。
905	func cloneHandover(h Handover) Handover {
906		out := h
907		out.CompletedAt = cloneTimePtr(h.CompletedAt)
908		if h.Entries != nil {
909			out.Entries = make([]HandoverEntry, len(h.Entries))
910			for i, e := range h.Entries {
911				out.Entries[i] = cloneEntry(e)
912			}
913		}
914		return out
915	}
916	
917	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
918	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
919	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
920	// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
921	// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
922	// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
923	// 也不会改写这份报告；再次查询才反映最新内容。
924	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
925		shiftID = clean(shiftID)
926		d := &svc.store.data
927		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
928		sh, _ := findShift(d, shiftID)
929		if sh == nil {
930			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
931		}
932		rep.Shift = cloneShift(*sh)
933	
934		for _, n := range d.Notes {
935			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
936				rep.OverlapNotes = append(rep.OverlapNotes, n)
937			}
938		}
939		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
940	
941		switch {
942		case !sh.Closed:
943			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
944			rep.Items = currentItemsOfShift(d, sh.ID)
945		case sh.CloseRecord != nil:
946			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
947			rep.ItemsAtClose = true
948			rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
949			for i, s := range sh.CloseRecord.Items {
950				rep.CloseItems[i] = cloneCloseItemSnapshot(s)
951			}
952			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
953			for _, s := range rep.CloseItems {
954				if it, _ := findItem(d, s.ItemID); it != nil {
955					rep.LatestItems[s.ItemID] = cloneItem(*it)
956				}
957			}
958		default:
959			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
960			rep.HistoryIncomplete = true
961			rep.Items = currentItemsOfShift(d, sh.ID)
962		}
963		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
964		for i := range rep.Items {
965			rep.Items[i] = cloneItem(rep.Items[i])
966		}
967	
968		for i := range d.Handovers {
969			h := &d.Handovers[i]
970			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
971			if !involved {
972				continue
973			}
974			if h.FromShiftID == sh.ID {
975				cp := cloneHandover(*h)
976				rep.Outgoing = &cp
977			}
978			if h.ToShiftID == sh.ID {
979				rep.Incoming = append(rep.Incoming, cloneHandover(*h))
980			}
981			for j := range h.Entries {
982				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
983					HandoverID: h.ID,
984					FromShift:  h.FromShiftID,
985					ToShift:    h.ToShiftID,
986					Entry:      cloneEntry(h.Entries[j]),
987				})
988			}
989		}
990		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
991		for k := range rep.Results {
992			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
993		}
994		return rep, nil
995	}
