1	package handover
2	
3	import (
4		"errors"
5		"os"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	// 本文件为“逐项退回”补充保存失败时的可重复回归保障：接班人填了有效操作人、
12	// 非空原因且事项当前允许退回（待处理），但本地数据在原子保存阶段失败。
13	// 通用的快照回滚（store.mutate）适用于退回，但之前没有针对退回的回归测试，
14	// 因此用两个用例分别覆盖首次退回与补充后再次退回这两种使用条件，并沿用既
15	// 有保存失败测试的同一套故障注入方式（在 .tmp 路径放目录使写入必然失败）。
16	
17	// failedReturnExpectations 汇总失败尝试发生前已保存的业务事实，供 reopen
18	// 前后用同一组期望核对。
19	type failedReturnExpectations struct {
20		hID                string
21		fromShift, toShift string
22		idA, idB           string
23		otherConfirmedAt   time.Time // 同交接中另一项已接收的处理时间
24		preRounds          int       // 失败尝试前已成功保存的退回轮次
25		r1ReturnedAt       time.Time // 第一轮成功退回时间
26		r1Reason           string
27		r1ResubmitAt       time.Time // 第一轮成功重新提交时间
28		r1Supplement       string
29		failAt             time.Time // 失败尝试时刻（不应留下任何痕迹）
30		failedReason       string    // 失败尝试填写的退回原因
31		failedOperator     string    // 失败尝试填写的操作人
32	}
33	
34	// assertPendingBeforeAnyReturn 用当前打开的数据核对“首次退回失败”后事实：
35	// 事项仍是待处理、接班人尚未处理，不产生退回轮次；失败尝试的原因、人名与
36	// 时刻都不是已发生的退回；同交接已确认的另一项与交班班次结束时记录不受影响。
37	func assertPendingBeforeAnyReturn(t *testing.T, f *fixture, w failedReturnExpectations) {
38		t.Helper()
39	
40		// 交接：整份交接继续未完成且没有完成时间；不生成第二条交接。
41		h, err := f.svc.GetHandover(w.hID)
42		if err != nil {
43			t.Fatalf("get handover: %v", err)
44		}
45		if h.Completed() || h.CompletedAt != nil {
46			t.Fatalf("保存失败后整份交接应继续未完成、不能留下完成时间：%+v", h)
47		}
48		if hs := f.svc.ListHandovers(); len(hs) != 1 || hs[0].ID != w.hID {
49			t.Fatalf("失败尝试不应生成另一条交接：%+v", hs)
50		}
51	
52		e := findEntryOf(t, h, w.idA)
53	
54		// 当前结果仍为待处理：接班人尚未处理，没有本次尝试的操作人、时间或原因。
55		if e.Status != EntryPending {
56			t.Fatalf("首次退回失败后该项应仍为待处理，got %s", e.Status)
57		}
58		if e.Operator != "" || e.ProcessedAt != nil {
59			t.Fatalf("待处理项的当前处理人与处理时间应仍为尚未处理：%+v", e)
60		}
61		if len(e.Rounds) != 0 {
62			t.Fatalf("首次退回失败不应产生退回轮次：%+v", e.Rounds)
63		}
64		if e.TrackingNote != "" {
65			t.Fatalf("失败尝试不应留下跟踪说明：%+v", e)
66		}
67	
68		// 同一份交接中另一项已经确认接收的结果、处理人和处理时间不受影响。
69		oe := findEntryOf(t, h, w.idB)
70		if oe.Status != EntryConfirmed || oe.Operator != "李四" ||
71			oe.ProcessedAt == nil || !oe.ProcessedAt.Equal(w.otherConfirmedAt) {
72			t.Fatalf("已接收的其他事项处理信息应保持原样：%+v", oe)
73		}
74		if len(oe.Rounds) != 0 {
75			t.Fatalf("其他事项不应被失败尝试增加退回经过：%+v", oe.Rounds)
76		}
77	
78		// 事项继续留在交班班次，原文、严重程度、限制条件与后续负责人保持原样，
79		// 流经班次不增加接班班次，历史不增加这次退回/接收。
80		assertItemStaysInFromShift(t, f, w, "事项甲", "李四")
81	
82		// 处理经过查询呈现失败前的事实：当前结果为待处理、接班人尚未处理；时间线
83		// 只有发起交接，没有退回、重新提交或接收，也不混入失败尝试的原因/时刻。
84		j, err := f.svc.ItemJourney(w.idA)
85		if err != nil {
86			t.Fatalf("journey: %v", err)
87		}
88		if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryPending {
89			t.Fatalf("处理经过中的交接当前结果应仍为待处理：%+v", j.Results)
90		}
91		if got := joinStrings(journeyKinds(j)); got != "created,handover-init" {
92			t.Fatalf("处理经过应只保留失败前事实（建立、发起交接），got %s", got)
93		}
94		assertNoFailedReturnTraceInJourney(t, w, j)
95		jText := FormatItemJourney(j)
96		if !strings.Contains(jText, "待处理（接班人尚未处理）") {
97			t.Fatalf("处理经过应显示待处理、接班人尚未处理：\n%s", jText)
98		}
99		if strings.Contains(jText, w.failedReason) {
100			t.Fatalf("失败尝试的退回原因不应出现在处理经过：\n%s", jText)
101		}
102		if strings.Contains(jText, w.failedOperator) {
103			t.Fatalf("失败尝试的操作人不应出现在处理经过：\n%s", jText)
104		}
105	
106		// 交接展示与保存事实一致：未完成、待处理项显示尚未处理，不出现失败尝试
107		// 的原因、人名或第1次退回记录。
108		text := FormatHandover(h)
109		if !strings.Contains(text, "[未完成]") {
110			t.Fatalf("交接应显示未完成：\n%s", text)
111		}
112		if !strings.Contains(text, "最后处理：尚未处理（等待接班人处理）；处理人=尚未处理；处理时间=尚未处理") {
113			t.Fatalf("待处理项应显示尚未处理：\n%s", text)
114		}
115		if strings.Contains(text, "第1次退回") || strings.Contains(text, "[退回]") {
116			t.Fatalf("首次退回失败不应留下退回状态或轮次展示：\n%s", text)
117		}
118		if strings.Contains(text, w.failedReason) || strings.Contains(text, w.failedOperator) {
119			t.Fatalf("失败尝试的原因与操作人不应出现在交接查询中：\n%s", text)
120		}
121		if strings.Contains(text, "已重新提交") {
122			t.Fatalf("首次退回失败不应出现重新提交记录：\n%s", text)
123		}
124	
125		// 交班班次结束时记录保留原来的内容与负责人。
126		assertFromShiftSnapshotUnchanged(t, f, w)
127	
128		// 待处理项使交接未完成，接班班次仍不能结束。
129		if _, err := f.svc.CloseShift(w.toShift); !errors.Is(err, ErrHandoverState) {
130			t.Fatalf("待处理项未接收时接班班次不能结束，got %v", err)
131		}
132	}
133	
134	// assertPendingAfterOneRound 用当前打开的数据核对“补充后再次退回失败”后事实：
135	// 该项仍是待处理（第一轮已成功退回、补充并重新提交，所以恢复为待处理），先前
136	// 那一轮的原因、退回人、退回时间、补充说明、补充人和重新提交时间全部保留，
137	// 不增加下一轮，也不把以前的补充改成这次尝试的内容。
138	func assertPendingAfterOneRound(t *testing.T, f *fixture, w failedReturnExpectations) {
139		t.Helper()
140	
141		h, err := f.svc.GetHandover(w.hID)
142		if err != nil {
143			t.Fatalf("get handover: %v", err)
144		}
145		if h.Completed() || h.CompletedAt != nil {
