172		}
173		if r1.Supplement != w.r1Supplement || r1.SupplementOperator != "张三" ||
174			r1.SupplementAt == nil || !r1.SupplementAt.Equal(w.r1ResubmitAt) ||
175			r1.ResubmittedAt == nil || !r1.ResubmittedAt.Equal(w.r1ResubmitAt) {
176			t.Fatalf("第一轮补充说明、补充人和重新提交时间应原样保留：%+v", r1)
177		}
178		if strings.Contains(r1.Supplement, w.failedReason) {
179			t.Fatalf("不得把以前的补充改成失败尝试的内容：%+v", r1)
