207		returns, resubmits := 0, 0
208		for _, ev := range j.Events {
209			switch ev.Kind {
210			case "return":
211				returns++
212				if ev.RoundSeq != 1 || !ev.TimeKnown || !ev.At.Equal(w.r1ReturnedAt) ||
