247		text := FormatHandover(h)
248		if !strings.Contains(text, "[未完成]") {
249			t.Fatalf("交接应显示未完成：\n%s", text)
250		}
251		if !strings.Contains(text, "最后处理：尚未处理（等待接班人处理）；处理人=尚未处理；处理时间=尚未处理") {
252			t.Fatalf("待处理项应显示尚未处理：\n%s", text)
253		}
254		if !strings.Contains(text, "第1次退回") || !strings.Contains(text, w.r1Reason) ||
255			!strings.Contains(text, w.r1Supplement) ||
256			!strings.Contains(text, "已重新提交："+fmtTime(w.r1ResubmitAt)) {
