294		}
295		for _, ev := range it.Events {
296			if ev.Kind == "received" {
297				t.Fatalf("失败尝试不应在事项历史留下接收记录：%+v", ev)
298			}
299			if !ev.At.IsZero() && ev.At.Equal(w.failAt) {
300				t.Fatalf("失败尝试时刻 %s 不应写入事项历史：%+v", w.failAt, ev)
301			}
302			if ev.Operator == w.failedOperator || strings.Contains(ev.Detail, w.failedReason) {
303				t.Fatalf("失败尝试的操作人与原因不应写入事项历史：%+v", ev)
304			}
305		}
306	}
