341	// TestReturnSaveFailureFirstAtomicRollback：首次退回时，接班人填写了有效操作人、
342	// 非空原因，事项也正处于允许退回的待处理状态，业务条件全部成立、真正进入保存
343	// 过程后本地写盘失败——退回操作必须明确返回保存错误，不能返回成功退回的结果；
344	// 内存与磁盘都回到失败前：该项仍是待处理、接班人尚未处理，不产生退回轮次，
345	// 失败尝试的原因、人名与时刻都不是已发生的退回，交接未完成、无完成时间，接班
346	// 班次不能结束，同交接已确认接收的另一项与交班班次结束时记录不受影响，原数据
347	// 文件一个字节不变。保存恢复后对同一事项重新执行退回，只新增一轮成功记录，
348	// 记录本次成功操作的原因、操作人与实际处理时间；失败尝试不占用轮次、不混入
349	// 经过。成功退回的当前结果明确表示等待交班人补充，事项仍留在交班班次，不因
350	// 这次退回而被接收。
351	func TestReturnSaveFailureFirstAtomicRollback(t *testing.T) {
352		f := newFixture(t)
353		a, b, items := prepareHandover(t, f)
354		h, err := f.svc.CreateHandover(a.ID, b.ID)
355		if err != nil {
356			t.Fatalf("create handover: %v", err)
357		}
358		idA, idB := items[0].ID, items[1].ID // 事项甲、事项乙（事项丙已关闭）
359	
360		// 同交接另一项先成功接收，后续核对它不受失败尝试影响。
361		otherConfirmedAt := tsDay(2, 16, 30)
362		f.svc.nowAt(func() time.Time { return otherConfirmedAt })
363		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionConfirm, "李四", "", "", ""); err != nil {
364			t.Fatalf("confirm other: %v", err)
365		}
366	
367		want := failedReturnExpectations{
368			hID: h.ID, fromShift: a.ID, toShift: b.ID, idA: idA, idB: idB,
369			otherConfirmedAt: otherConfirmedAt,
370			preRounds:        0,
371			failAt:           tsDay(2, 17, 0),
372			failedReason:     "第一次退回原因-失败尝试",
373			failedOperator:   "接班人王五",
374		}
375	
376		// 记录失败前已落盘的文件内容，并固定失败尝试的处理时刻。
377		rawBefore, err := os.ReadFile(f.store.Path())
378		if err != nil {
379			t.Fatalf("read data file: %v", err)
380		}
381		f.svc.nowAt(func() time.Time { return want.failAt })
382	
383		// 操作人有效、原因非空、事项待处理允许退回；使下一次写盘在原子保存阶段失败。
384		breakSaving(t, f)
385		_, err = f.svc.ProcessEntry(h.ID, idA, ActionReturn, want.failedOperator, want.failedReason, "", "")
386		if err == nil {
387			t.Fatalf("保存失败时退回应明确返回错误，不能返回成功退回的结果")
388		}
389		if !strings.Contains(err.Error(), "写入数据文件失败") {
390			t.Fatalf("应明确返回保存阶段的错误，got %v", err)
391		}
392		// 业务条件全部成立，不能用缺少原因、操作人为空、编号不存在或状态不允许的
393		// 拒绝来冒充这个保存失败场景。
394		if errors.Is(err, ErrInvalidInput) || errors.Is(err, ErrHandoverState) || errors.Is(err, ErrNotFound) {
395			t.Fatalf("参数合法、状态允许时的保存失败不应被报告为业务校验错误，got %v", err)
396		}
397	
398		// 当前打开的数据上查看交接与处理经过，应看到失败前的事实，而不是只保证
399		// 文件没变、查询却显示已经退回。
400		assertPendingBeforeAnyReturn(t, f, want)
401	
402		// 失败前已保存的数据文件一个字节都不应改变（原子改名未发生）。
403		rawAfter, err := os.ReadFile(f.store.Path())
404		if err != nil {
405			t.Fatalf("read data file after failure: %v", err)
406		}
407		if string(rawAfter) != string(rawBefore) {
408			t.Fatalf("保存失败不得改动既有数据文件，失败的退回不能成为其中的业务事实")
409		}
410	
411		// 退出后重新打开：仍是待处理、无退回轮次，失败尝试不产生任何退回事实。
412		f.reopen(t)
413		assertPendingBeforeAnyReturn(t, f, want)
414	
415		// 保存恢复正常后，对同一事项重新执行退回：按现有功能成功，只新增一轮。
416		restoreSaving(t, f)
417		successAt := tsDay(2, 18, 0)
418		successReason := "第一次退回原因-成功"
419		f.svc.nowAt(func() time.Time { return successAt })
420		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", successReason, "", ""); err != nil {
421			t.Fatalf("恢复后退回应成功：%v", err)
422		}
423	
424		// 交接：只成功退回这一轮，记录本次成功操作的原因、操作人与实际处理时间；
425		// 失败尝试不占用轮次（成功记录是第1轮而不是第2轮）。
426		h2, err := f.svc.GetHandover(h.ID)
427		if err != nil {
428			t.Fatalf("get handover after retry: %v", err)
429		}
430		if h2.Completed() || h2.CompletedAt != nil {
431			t.Fatalf("退回不接收事项，整份交接应继续未完成、无完成时间：%+v", h2)
432		}
433		le := findEntryOf(t, h2, idA)
434		if le.Status != EntryReturned || le.Operator != "李四" ||
435			le.ProcessedAt == nil || !le.ProcessedAt.Equal(successAt) {
436			t.Fatalf("当前结果应为本次成功退回，记录成功操作人与实际处理时间：%+v", le)
437		}
438		if len(le.Rounds) != 1 {
439			t.Fatalf("失败尝试不占用轮次，成功后应只有一轮，got %d：%+v", len(le.Rounds), le.Rounds)
440		}
441		r := le.Rounds[0]
442		if r.Seq != 1 || r.Reason != successReason || r.ReturnOperator != "李四" ||
443			!r.ReturnedAt.Equal(successAt) || r.Supplement != "" || r.ResubmittedAt != nil {
444			t.Fatalf("第1轮应只记录本次成功退回：%+v", r)
445		}
446	
447		// 事项仍留在交班班次，没有被这次退回接收，原文、负责人不变。
448		it, err := f.svc.GetItem(idA)
449		if err != nil {
450			t.Fatalf("get item after retry: %v", err)
451		}
452		if it.CurrentShiftID != a.ID || len(it.ShiftIDs) != 1 || it.ShiftIDs[0] != a.ID {
453			t.Fatalf("成功退回不应接收事项，应仍留在交班班次：%+v", it)
454		}
455		if it.Content != "事项甲" || it.FollowOwner != "李四" {
456			t.Fatalf("事项原文与后续负责人应不变：%+v", it)
457		}
458	
459		// 处理经过只呈现成功的这一次退回，明确等待交班人补充，不混入失败尝试。
460		j, err := f.svc.ItemJourney(idA)
461		if err != nil {
462			t.Fatalf("journey after retry: %v", err)
463		}
464		if got := joinStrings(journeyKinds(j)); got != "created,handover-init,return" {
465			t.Fatalf("处理经过应只留下成功的一次退回，got %s", got)
466		}
467		returns := 0
468		for _, ev := range j.Events {
469			if ev.Kind == "return" {
470				returns++
471				if !ev.TimeKnown || !ev.At.Equal(successAt) || ev.Operator != "李四" ||
472					ev.RoundSeq != 1 || ev.Reason != successReason {
473					t.Fatalf("成功退回事件内容不正确：%+v", ev)
474				}
475			}
476			if ev.TimeKnown && ev.At.Equal(want.failAt) {
477				t.Fatalf("失败尝试时刻不应出现在处理经过：%+v", ev)
478			}
479			if ev.Operator == want.failedOperator || strings.Contains(ev.Reason, want.failedReason) {
480				t.Fatalf("失败尝试的人名与原因不应混入处理经过：%+v", ev)
481			}
482		}
483		if returns != 1 {
484			t.Fatalf("应只有一次退回记录，got %d", returns)
485		}
486		if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryReturned {
487			t.Fatalf("交接当前结果应为退回：%+v", j.Results)
488		}
489		jText := FormatItemJourney(j)
490		if !strings.Contains(jText, "退回（等待交班人补充）") {
491			t.Fatalf("成功退回的当前结果应明确表示等待交班人补充：\n%s", jText)
492		}
493		if strings.Contains(jText, want.failedReason) || strings.Contains(jText, want.failedOperator) {
494			t.Fatalf("失败尝试的原因与人名不能混入成功后的处理经过：\n%s", jText)
495		}
496		text := FormatHandover(h2)
497		if !strings.Contains(text, "[退回]") || !strings.Contains(text, "第1次退回") ||
498			!strings.Contains(text, successReason) {
499			t.Fatalf("交接查询应展示成功退回与第1轮原因：\n%s", text)
500		}
501		if strings.Contains(text, want.failedReason) || strings.Contains(text, want.failedOperator) ||
502			strings.Contains(text, fmtTime(want.failAt)) {
503			t.Fatalf("失败尝试的原因、人名与时刻不应出现在交接查询中：\n%s", text)
504		}
505	
506		// 退回等待补充期间接班班次仍不能结束。
507		if _, err := f.svc.CloseShift(b.ID); !errors.Is(err, ErrHandoverState) {
508			t.Fatalf("退回项等待补充时接班班次不能结束，got %v", err)
509		}
510	
511		// 成功落盘的文件只包含成功事实，不包含失败尝试的原因、人名与时刻。
512		rawSuccess, err := os.ReadFile(f.store.Path())
513		if err != nil {
514			t.Fatalf("read data file after success: %v", err)
515		}
516		if !strings.Contains(string(rawSuccess), successAt.Format("2006-01-02T15:04:05-07:00")) ||
517			!strings.Contains(string(rawSuccess), successReason) {
518			t.Fatalf("成功退回的时间与原因应已写入数据文件")
519		}
520		if strings.Contains(string(rawSuccess), want.failAt.Format("2006-01-02T15:04:05-07:00")) ||
521			strings.Contains(string(rawSuccess), want.failedReason) ||
522			strings.Contains(string(rawSuccess), want.failedOperator) {
523			t.Fatalf("失败尝试的时刻、原因与人名不应留在数据文件中")
524		}
525	
526		// 退出重开后，成功退回的事实完整保留，失败尝试仍无痕迹。
527		f.reopen(t)
528		h3, err := f.svc.GetHandover(h.ID)
529		if err != nil {
530			t.Fatalf("reopen get handover: %v", err)
531		}
532		if h3.Completed() || h3.CompletedAt != nil {
533			t.Fatalf("重开后交接仍应未完成：%+v", h3)
534		}
535		re := findEntryOf(t, h3, idA)
536		if re.Status != EntryReturned || len(re.Rounds) != 1 ||
537			re.Rounds[0].Reason != successReason || re.Rounds[0].ReturnOperator != "李四" {
538			t.Fatalf("重开后成功退回的一轮应完整保留：%+v", re)
539		}
540		j3, err := f.svc.ItemJourney(idA)
541		if err != nil {
542			t.Fatalf("reopen journey: %v", err)
543		}
544		if got := joinStrings(journeyKinds(j3)); got != "created,handover-init,return" {
545			t.Fatalf("重开后处理经过应只保留成功的一次退回，got %s", got)
546		}
547	}
548	
549	// TestReturnSaveFailureSecondAfterResubmitAtomicRollback：事项已经成功退回过
550	// 一轮、交班人补充并重新提交（恢复待处理）后，接班人再次退回时填写了有效
551	// 操作人、非空原因且状态允许，但本地写盘失败——操作必须明确失败，不能当成
552	// 退回成功；内存与磁盘都回到失败前：该项仍是待处理，先前那一轮的原因、退回人、
553	// 退回时间、补充说明、补充人和重新提交时间全部保留，不增加下一轮，也不把以前
554	// 的补充改成这次尝试的内容；同交接已接收的另一项不受影响。保存恢复后对同一
555	// 事项再次退回，只新增一轮（第2轮）成功记录；随后交班人补充重新提交、接班人
556	// 确认接收的既有规则仍成立，整份交接在确认时刻才完成。
557	func TestReturnSaveFailureSecondAfterResubmitAtomicRollback(t *testing.T) {
558		f := newFixture(t)
559		a, b, items := prepareHandover(t, f)
560		h, err := f.svc.CreateHandover(a.ID, b.ID)
561		if err != nil {
562			t.Fatalf("create handover: %v", err)
563		}
564		idA, idB := items[0].ID, items[1].ID
565	
566		// 同交接另一项先成功接收。
567		otherConfirmedAt := tsDay(2, 16, 30)
568		f.svc.nowAt(func() time.Time { return otherConfirmedAt })
569		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionConfirm, "李四", "", "", ""); err != nil {
570			t.Fatalf("confirm other: %v", err)
571		}
572	
573		// 第一轮：成功退回 -> 交班人补充并重新提交，事项恢复待处理。
574		r1ReturnedAt := tsDay(2, 17, 0)
575		f.svc.nowAt(func() time.Time { return r1ReturnedAt })
576		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "第一轮原因", "", ""); err != nil {
577			t.Fatalf("return round 1: %v", err)
578		}
579		r1ResubmitAt := tsDay(2, 17, 30)
580		f.svc.nowAt(func() time.Time { return r1ResubmitAt })
581		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "第一轮补充内容"); err != nil {
582			t.Fatalf("resubmit round 1: %v", err)
583		}
584		pre, _ := f.svc.GetHandover(h.ID)
585		preEntry := findEntryOf(t, pre, idA)
586		if preEntry.Status != EntryPending || len(preEntry.Rounds) != 1 ||
587			preEntry.Rounds[0].ResubmittedAt == nil {
588			t.Fatalf("前置：事项应已补充重新提交、恢复待处理且保留一轮：%+v", preEntry)
589		}
590	
591		want := failedReturnExpectations{
592			hID: h.ID, fromShift: a.ID, toShift: b.ID, idA: idA, idB: idB,
593			otherConfirmedAt: otherConfirmedAt,
594			preRounds:        1,
595			r1ReturnedAt:     r1ReturnedAt, r1Reason: "第一轮原因",
596			r1ResubmitAt: r1ResubmitAt, r1Supplement: "第一轮补充内容",
597			failAt:         tsDay(2, 18, 0),
598			failedReason:   "第二轮退回原因-失败尝试",
599			failedOperator: "接班人王五",
600		}
601	
602		rawBefore, err := os.ReadFile(f.store.Path())
603		if err != nil {
604			t.Fatalf("read data file: %v", err)
605		}
606		f.svc.nowAt(func() time.Time { return want.failAt })
607	
608		// 再次退回：操作人有效、原因非空、事项待处理允许退回；写盘在保存阶段失败。
609		breakSaving(t, f)
610		_, err = f.svc.ProcessEntry(h.ID, idA, ActionReturn, want.failedOperator, want.failedReason, "", "")
611		if err == nil {
612			t.Fatalf("保存失败时再次退回应明确返回错误，不能返回成功退回的结果")
613		}
614		if !strings.Contains(err.Error(), "写入数据文件失败") {
615			t.Fatalf("应明确返回保存阶段的错误，got %v", err)
616		}
617		if errors.Is(err, ErrInvalidInput) || errors.Is(err, ErrHandoverState) || errors.Is(err, ErrNotFound) {
618			t.Fatalf("参数合法、状态允许时的保存失败不应被报告为业务校验错误，got %v", err)
619		}
620	
621		assertPendingAfterOneRound(t, f, want)
622	
623		rawAfter, err := os.ReadFile(f.store.Path())
624		if err != nil {
625			t.Fatalf("read data file after failure: %v", err)
626		}
627		if string(rawAfter) != string(rawBefore) {
628			t.Fatalf("保存失败不得改动既有数据文件，失败的退回不能成为其中的业务事实")
629		}
630	
631		f.reopen(t)
632		assertPendingAfterOneRound(t, f, want)
633	
634		// 保存恢复正常后再次退回：只新增第2轮成功记录，失败尝试不占用轮次。
635		restoreSaving(t, f)
636		successAt := tsDay(2, 19, 0)
637		successReason := "第二轮退回原因-成功"
638		f.svc.nowAt(func() time.Time { return successAt })
639		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", successReason, "", ""); err != nil {
640			t.Fatalf("恢复后再次退回应成功：%v", err)
641		}
642	
643		h2, err := f.svc.GetHandover(h.ID)
644		if err != nil {
645			t.Fatalf("get handover after retry: %v", err)
646		}
647		if h2.Completed() || h2.CompletedAt != nil {
648			t.Fatalf("再次退回不接收事项，交接应继续未完成：%+v", h2)
649		}
650		le := findEntryOf(t, h2, idA)
651		if le.Status != EntryReturned || le.Operator != "李四" ||
652			le.ProcessedAt == nil || !le.ProcessedAt.Equal(successAt) {
653			t.Fatalf("当前结果应为本次成功退回：%+v", le)
654		}
655		if len(le.Rounds) != 2 {
656			t.Fatalf("失败尝试不占用轮次，成功后应只有两轮，got %d：%+v", len(le.Rounds), le.Rounds)
657		}
658		s1, s2 := le.Rounds[0], le.Rounds[1]
659		// 先前那一轮完整保留。
660		if s1.Seq != 1 || s1.Reason != want.r1Reason || s1.ReturnOperator != "李四" ||
661			!s1.ReturnedAt.Equal(want.r1ReturnedAt) ||
662			s1.Supplement != want.r1Supplement || s1.SupplementOperator != "张三" ||
663			s1.SupplementAt == nil || !s1.SupplementAt.Equal(want.r1ResubmitAt) ||
664			s1.ResubmittedAt == nil || !s1.ResubmittedAt.Equal(want.r1ResubmitAt) {
