668		if s2.Seq != 2 || s2.Reason != successReason || s2.ReturnOperator != "李四" ||
669			!s2.ReturnedAt.Equal(successAt) || s2.Supplement != "" ||
670			s2.SupplementOperator != "" || s2.ResubmittedAt != nil {
