678		}
679		if it.CurrentShiftID != a.ID || len(it.ShiftIDs) != 1 || it.ShiftIDs[0] != a.ID {
680			t.Fatalf("再次退回成功不应接收事项，应仍留在交班班次：%+v", it)
681		}
