686		// 处理经过：两轮退回（第2轮只反映成功操作）与第一轮重新提交，不混入失败
687		// 尝试的原因、人名或时刻。
688		j, err := f.svc.ItemJourney(idA)
689		if err != nil {
690			t.Fatalf("journey after retry: %v", err)
691		}
692		if got := joinStrings(journeyKinds(j)); got != "created,handover-init,return,resubmit,return" {
693			t.Fatalf("处理经过应呈现两轮成功退回与第一轮重新提交，got %s", got)
694		}
695		secondReturns := 0
696		for _, ev := range j.Events {
697			if ev.TimeKnown && ev.At.Equal(want.failAt) {
698				t.Fatalf("失败尝试时刻不应出现在处理经过：%+v", ev)
699			}
700			if ev.Operator == want.failedOperator || strings.Contains(ev.Reason, want.failedReason) ||
701				strings.Contains(ev.Supplement, want.failedReason) {
702				t.Fatalf("失败尝试的人名与原因不能混入处理经过：%+v", ev)
703			}
704			if ev.Kind == "return" && ev.RoundSeq == 2 {
705				secondReturns++
706				if !ev.TimeKnown || !ev.At.Equal(successAt) || ev.Operator != "李四" ||
707					ev.Reason != successReason {
708					t.Fatalf("第2轮退回应只反映成功操作：%+v", ev)
709				}
710			}
711		}
712		if secondReturns != 1 {
713			t.Fatalf("第2轮应只有一次（成功的）退回，got %d", secondReturns)
714		}
715		jText := FormatItemJourney(j)
716		if !strings.Contains(jText, "退回（等待交班人补充）") {
717			t.Fatalf("成功退回的当前结果应明确表示等待交班人补充：\n%s", jText)
718		}
719		if strings.Contains(jText, want.failedReason) || strings.Contains(jText, want.failedOperator) {
720			t.Fatalf("失败尝试的原因与人名不能混入成功后的处理经过：\n%s", jText)
721		}
722	
723		// 退回等待补充期间接班班次不能结束。
724		if _, err := f.svc.CloseShift(b.ID); !errors.Is(err, ErrHandoverState) {
