1469		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); !errors.Is(err, ErrHandoverState) {
1470			t.Fatalf("第二轮退回后必须重新提交，got %v", err)
1471		}
1472		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionTrack, "李四", "", "说明", "王五"); !errors.Is(err, ErrHandoverState) {
1473			t.Fatalf("第二轮退回后继续跟踪也必须拦截，got %v", err)
1474		}
1475		got, _ = f.svc.GetHandover(h.ID)
1476		ea = findEntryOf(t, got, idA)
1477		r1, r2 := ea.Rounds[0], ea.Rounds[1]
