1491		}
1492		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionTrack, "李四", "", "持续跟进", "王五"); err != nil {
1493			t.Fatalf("第二轮重新提交后应能继续跟踪：%v", err)
1494		}
