597	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
598	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
599	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
600	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
601	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
602	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
603	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
604	// 只有本地数据保存成功才算处理完成：输入合法、该项允许处理且实际进入保存阶段后，
605	// 无论写入临时文件失败还是最终保存失败，内存变更都随快照一并回滚，返回原保存错误
606	// 与零值交接结果（编号、岗位、两班编号为空，发起时间为零值，完成时间为空，清单
607	// 没有事项），不把本次尝试形成的处理状态、操作人、处理时间、跟踪说明、新增退回
608	// 轮次或交接完成时间当作处理结果，也不返回失败前的整份交接充当处理结果；最后一项
609	// 的失败尝试同样不能通过返回结果宣称整份交接完成。输入不合法或状态不允许的业务
610	// 拒绝发生在保存之前，同样不返回交接结果。
611	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
612		handoverID = clean(handoverID)
613		itemID = clean(itemID)
614		operator = clean(operator)
615		reason = clean(reason)
616		trackingNote = clean(trackingNote)
617		nextFollowOwner = clean(nextFollowOwner)
618	
619		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
620			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
621		}
622		if err := requireNonEmpty("操作人", operator); err != nil {
623			return Handover{}, err
624		}
625	
626		var result Handover
627		err := svc.store.mutate(func(d *Data) error {
628			h, _ := findHandover(d, handoverID)
629			if h == nil {
630				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
631			}
632			e, _ := findEntry(h, itemID)
633			if e == nil {
634				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
635			}
636			if e.Status.Received() {
637				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
638					ErrHandoverState, e.ItemID, e.Status.Label())
639			}
640			if e.Status == EntryReturned {
641				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
642				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
643				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
644				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
645					ErrHandoverState, e.ItemID, h.ID)
646			}
647			switch action {
648			case ActionReturn:
649				if err := requireNonEmpty("退回原因", reason); err != nil {
650					return err
651				}
652			case ActionTrack:
653				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
654					return err
655				}
656				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
657					return err
658				}
659			}
660	
661			now := svc.now()
662			switch action {
663			case ActionConfirm:
664				e.Status = EntryConfirmed
665			case ActionTrack:
666				e.Status = EntryTracking
667				e.TrackingNote = trackingNote
668				e.FollowOwner = nextFollowOwner
669			case ActionReturn:
670				e.Status = EntryReturned
671				e.Rounds = append(e.Rounds, ReturnRound{
672					Seq:            len(e.Rounds) + 1,
673					ReturnedAt:     now,
674					ReturnOperator: operator,
675					Reason:         reason,
676				})
